app_css:
.tool-app-paychaser { color: #3b0d0d; max-width: 860px; margin-inline:auto; }
.tool-app-paychaser .pc-stats { display: grid; grid-template-columns: repeat(auto-fit, minmax(150px, 1fr)); gap: 10px; margin: 0 0 16px; }
.tool-app-paychaser .pc-stat { background: #fef2f2; border: 1px solid #fecaca; border-radius: 12px; padding: 12px 14px; display: flex; flex-direction: column; gap: 4px; }
.tool-app-paychaser .pc-stat span { font-size: 12px; font-weight: 600; color: #991b1b; }
.tool-app-paychaser .pc-stat strong { font-size: 22px; }
.tool-app-paychaser .pc-form { display: grid; grid-template-columns: repeat(auto-fit, minmax(150px, 1fr)); gap: 10px; margin-bottom: 18px; }
.tool-app-paychaser label { display: flex; flex-direction: column; font-size: 12px; font-weight: 600; gap: 4px; }
.tool-app-paychaser input[type="text"], .tool-app-paychaser input[type="number"], .tool-app-paychaser input[type="date"], .tool-app-paychaser textarea { border: 1px solid #fecaca; border-radius: 8px; padding: 8px 10px; font-size: 14px; width: 100%; box-sizing: border-box; }
.tool-app-paychaser .pc-form .pc-btn { grid-column: 1 / -1; justify-self: start; }
.tool-app-paychaser .pc-btn { background: #DC2626; color: #fff; border: none; border-radius: 10px; padding: 10px 18px; font-size: 14px; font-weight: 700; cursor: pointer; }
.tool-app-paychaser .pc-btn:hover { background: #b91c1c; }
.tool-app-paychaser .pc-btn-ghost { background: #fee2e2; color: #DC2626; }
.tool-app-paychaser .pc-btn-ghost:hover { background: #fecaca; }
.tool-app-paychaser .pc-btn-danger { background: none; color: #b91c1c; }
.tool-app-paychaser .pc-btn-danger:hover { background: #fef2f2; }
.tool-app-paychaser .pc-h { margin: 18px 0 8px; }
.tool-app-paychaser .pc-list { list-style: none; padding: 0; margin: 0; }
.tool-app-paychaser .pc-list li { display: flex; align-items: center; gap: 12px; flex-wrap: wrap; background: #fff7f7; border: 1px solid #fecaca; border-radius: 10px; padding: 10px 12px; margin-bottom: 8px; font-size: 14px; }
.tool-app-paychaser .pc-list .pc-li-main { flex: 1 1 220px; }
.tool-app-paychaser .pc-list .pc-li-main strong { display: block; }
.tool-app-paychaser .pc-list .pc-li-main small { color: #991b1b; }
.tool-app-paychaser .pc-badge { font-size: 12px; font-weight: 700; border-radius: 999px; padding: 3px 10px; white-space: nowrap; }
.tool-app-paychaser .pc-badge-overdue { background: #DC2626; color: #fff; }
.tool-app-paychaser .pc-badge-due { background: #fde68a; color: #92400e; }
.tool-app-paychaser .pc-li-amt { font-weight: 800; font-size: 16px; }
.tool-app-paychaser .pc-list button { background: #fee2e2; color: #DC2626; border: none; border-radius: 8px; padding: 7px 12px; font-weight: 700; cursor: pointer; font-size: 13px; }
.tool-app-paychaser .pc-list button:hover { background: #fecaca; }
.tool-app-paychaser .pc-empty { background: #f9fafb; border-radius: 10px; padding: 14px; font-size: 14px; color: #6b7280; margin: 0; }
.tool-app-paychaser .pc-detail { margin-top: 20px; border-top: 2px solid #fecaca; padding-top: 8px; }
.tool-app-paychaser .pc-tabs { display: flex; gap: 8px; flex-wrap: wrap; margin: 10px 0; }
.tool-app-paychaser .pc-tab { border: 1px solid #fecaca; background: #fff; border-radius: 999px; padding: 8px 14px; font-size: 13px; font-weight: 700; cursor: pointer; color: #7f1d1d; }
.tool-app-paychaser .pc-tab.pc-active { background: #DC2626; border-color: #DC2626; color: #fff; }
.tool-app-paychaser .pc-hint { font-size: 13px; color: #991b1b; margin: 4px 0 10px; }
.tool-app-paychaser .pc-actions { display: flex; gap: 10px; margin: 14px 0; flex-wrap: wrap; }
.tool-app-paychaser #pc-copy.pc-copied { background: #059669; }
.tool-app-paychaser .pc-detail label { margin: 10px 0 0; }

app_js:
(function () {
  'use strict';
  function $(id) { return document.getElementById(id); }
  function esc(s) {
    return String(s == null ? '' : s).replace(/[&<>"']/g, function (c) {
      return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c];
    });
  }
  function money(n) { n = parseFloat(n); return '$' + (isFinite(n) ? n : 0).toFixed(2); }
  function todayStr() { var d = new Date(); return d.getFullYear() + '-' + String(d.getMonth() + 1).padStart(2, '0') + '-' + String(d.getDate()).padStart(2, '0'); }
  function daysOverdue(dueStr) {
    if (!dueStr) return 0;
    var due = new Date(dueStr + 'T12:00:00');
    var now = new Date(todayStr() + 'T12:00:00');
    return Math.round((now - due) / 864e5);
  }
  function stageText(inv, days, stage) {
    var client = inv.client || 'there';
    var biz = inv.biz ? ' at ' + inv.biz : '';
    var amount = money(inv.amount);
    var num = inv.number ? ' ' + inv.number : '';
    var late = days > 0 ? days + ' days overdue' : 'due soon';
    var subject, body;
    if (stage === 0) {
      subject = 'Quick reminder: invoice' + num + ' (' + amount + ')';
      body = 'Hi ' + client + ',\n\nJust a quick heads-up that invoice' + num + ' for ' + amount + ' was due on ' + inv.duedate + '.\n\nIt may have slipped through the cracks \u2014 totally normal. Could you let me know when I can expect payment?\n\nThanks so much,\n' + (inv.biz || 'Us');
    } else if (stage === 1) {
      subject = 'Overdue invoice' + num + ': ' + amount + ' (' + days + ' days late)';
      body = 'Hi ' + client + ',\n\nI\u2019m following up on invoice' + num + ' for ' + amount + ', which is now ' + late + ' (due ' + inv.duedate + ').\n\nIf payment is on the way, please ignore this. Otherwise, could you confirm a payment date this week? If there\u2019s an issue with the invoice, I\u2019d rather hear about it now so we can sort it out.\n\nThanks,\n' + (inv.biz || 'Us') + '\nAccounts';
    } else {
      subject = 'Final notice: invoice' + num + ' (' + amount + ') due ' + inv.duedate;
      body = 'Hi ' + client + ',\n\nThis is a final notice regarding invoice' + num + ' for ' + amount + ', now ' + late + '.\n\nIf payment isn\u2019t received within 7 days, I\u2019ll have to pause any ongoing work and pass the balance to collections. I\u2019d much rather avoid that.\n\nPlease pay by ' + inv.duedate + ' terms immediately, or reply with a firm payment date.\n\nRegards,\n' + (inv.biz || 'Us') + '\nAccounts';
    }
    return { subject: subject, body: body };
  }
  var HINTS = [
    'Send this when the invoice is new or just past due. Warm, assumes it slipped through the cracks.',
    'Send this 7+ days overdue. Direct, names the number of days, asks for a payment date.',
    'Send this 30+ days overdue. Final notice: states consequences and a hard 7-day deadline.'
  ];
  var LS_KEY = 'toolapp-paychaser-invoices';
  var state = { selectedId: null, stage: 0 };
  function getInvoices() {
    try { return JSON.parse(localStorage.getItem(LS_KEY)) || []; } catch (e) { return []; }
  }
  function setInvoices(v) {
    try { localStorage.setItem(LS_KEY, JSON.stringify(v)); } catch (e) {}
  }
  function getSelected() {
    var invs = getInvoices();
    for (var i = 0; i < invs.length; i++) {
      if (invs[i].id === state.selectedId) return invs[i];
    }
    return null;
  }
  function saveSelected(mut) {
    var invs = getInvoices();
    for (var i = 0; i < invs.length; i++) {
      if (invs[i].id === state.selectedId) {
        mut(invs[i]);
        setInvoices(invs);
        return;
      }
    }
  }
  function renderStats() {
    var invs = getInvoices();
    var total = 0, overdue = 0, oldest = 0;
    for (var i = 0; i < invs.length; i++) {
      total += parseFloat(invs[i].amount) || 0;
      var d = daysOverdue(invs[i].duedate);
      if (d > 0) overdue++;
      if (d > oldest) oldest = d;
    }
    $('pc-outstanding').textContent = money(total);
    $('pc-count').textContent = String(invs.length);
    $('pc-oldest').textContent = overdue ? (oldest + (oldest === 1 ? ' day' : ' days')) : '\u2014';
  }
  function overdueLabel(d) {
    if (d > 0) return d + (d === 1 ? ' day overdue' : ' days overdue');
    if (d === 0) return 'Due today';
    return 'Due in ' + (-d) + (-d === 1 ? ' day' : ' days');
  }
  function renderList() {
    var invs = getInvoices();
    invs.sort(function (a, b) { return daysOverdue(b.duedate) - daysOverdue(a.duedate); });
    var ul = $('pc-list');
    ul.innerHTML = '';
    if (!invs.length) {
      var p = document.createElement('p');
      p.className = 'pc-empty';
      p.textContent = 'No open invoices. Add one above and PayChaser will track it and draft your chasers.';
      ul.appendChild(p);
      return;
    }
    for (var i = 0; i < invs.length; i++) {
      (function (inv) {
        var d = daysOverdue(inv.duedate);
        var li = document.createElement('li');
        var main = document.createElement('div');
        main.className = 'pc-li-main';
        var title = document.createElement('strong');
        title.textContent = (inv.number || 'Invoice') + ' \u2014 ' + (inv.client || 'Unknown client');
        var sub = document.createElement('small');
        sub.textContent = inv.duedate ? ('Due ' + inv.duedate) : 'No due date';
        main.appendChild(title);
        main.appendChild(sub);
        var badge = document.createElement('span');
        badge.className = 'pc-badge ' + (d > 0 ? 'pc-badge-overdue' : 'pc-badge-due');
        badge.textContent = overdueLabel(d);
        var amt = document.createElement('span');
        amt.className = 'pc-li-amt';
        amt.textContent = money(inv.amount);
        var btn = document.createElement('button');
        btn.type = 'button';
        btn.textContent = 'Draft chaser';
        btn.addEventListener('click', function () { selectInvoice(inv.id); });
        li.appendChild(main);
        li.appendChild(badge);
        li.appendChild(amt);
        li.appendChild(btn);
        ul.appendChild(li);
      })(invs[i]);
    }
  }
  function selectInvoice(id) {
    var inv = null;
    var invs = getInvoices();
    for (var i = 0; i < invs.length; i++) { if (invs[i].id === id) inv = invs[i]; }
    if (!inv) return;
    state.selectedId = id;
    var d = daysOverdue(inv.duedate);
    state.stage = d >= 30 ? 2 : (d >= 7 ? 1 : 0);
    renderDetail();
  }
  function renderDetail() {
    var inv = getSelected();
    var box = $('pc-detail');
    if (!inv) { box.hidden = true; return; }
    box.hidden = false;
    var d = daysOverdue(inv.duedate);
    $('pc-detail-title').textContent = (inv.number || 'Invoice') + ' \u2014 ' + (inv.client || 'Unknown client') + ' \u2014 ' + money(inv.amount);
    var tabs = box.querySelectorAll('.pc-tab');
    for (var i = 0; i < tabs.length; i++) {
      tabs[i].classList.toggle('pc-active', parseInt(tabs[i].getAttribute('data-stage'), 10) === state.stage);
    }
    $('pc-hint').textContent = HINTS[state.stage];
    var t = stageText(inv, d, state.stage);
    $('pc-subject').value = t.subject;
    $('pc-body').value = t.body;
  }
  function copyDraft() {
    var inv = getSelected();
    if (!inv) return;
    var text = 'Subject: ' + $('pc-subject').value + '\n\n' + $('pc-body').value;
    function done() {
      var b = $('pc-copy');
      b.classList.add('pc-copied');
      var old = b.textContent;
      b.textContent = 'Copied!';
      setTimeout(function () { b.classList.remove('pc-copied'); b.textContent = old; }, 1600);
    }
    if (navigator.clipboard && navigator.clipboard.writeText) {
      navigator.clipboard.writeText(text).then(done, done);
    } else {
      var ta = document.createElement('textarea');
      ta.value = text;
      document.body.appendChild(ta);
      ta.select();
      try { document.execCommand('copy'); } catch (e) {}
      document.body.removeChild(ta);
      done();
    }
  }
  function addInvoice() {
    var amount = parseFloat($('pc-amount').value);
    var inv = {
      id: 'pc-' + Date.now().toString(36) + Math.floor(Math.random() * 1e6).toString(36),
      biz: $('pc-biz').value.trim(),
      client: $('pc-client').value.trim(),
      number: $('pc-invoice').value.trim(),
      amount: isFinite(amount) ? amount : 0,
      duedate: $('pc-duedate').value
    };
    if (!inv.client && !inv.number) {
      $('pc-client').focus();
      return;
    }
    var invs = getInvoices();
    invs.unshift(inv);
    setInvoices(invs.slice(0, 200));
    $('pc-client').value = '';
    $('pc-invoice').value = '';
    $('pc-amount').value = '';
    $('pc-duedate').value = todayStr();
    renderStats();
    renderList();
    selectInvoice(inv.id);
  }
  (function init() {
    $('pc-form').addEventListener('submit', function (e) { e.preventDefault(); addInvoice(); });
    $('pc-duedate').value = todayStr();
    $('pc-detail').addEventListener('click', function (e) {
      var t = e.target;
      if (t.classList && t.classList.contains('pc-tab')) {
        state.stage = parseInt(t.getAttribute('data-stage'), 10);
        renderDetail();
        return;
      }
      if (t.id === 'pc-copy') { copyDraft(); return; }
      if (t.id === 'pc-paid' || t.id === 'pc-remove') {
        var invs = getInvoices();
        var out = [];
        for (var i = 0; i < invs.length; i++) {
          if (invs[i].id !== state.selectedId) out.push(invs[i]);
        }
        setInvoices(out);
        state.selectedId = null;
        renderStats();
        renderList();
        renderDetail();
      }
    });
    renderStats();
    renderList();
    renderDetail();
  })();
})();
